{
  "findings": [
    {
      "check_id": "CKV_GCP_14",
      "title": "Overly permissive IAM role assignment",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "HIGH",
      "explanation": "The 'roles/editor' role grants broad permissions, including write access to many resources. This can lead to privilege escalation or accidental changes. It is recommended to use more granular roles tailored to the specific needs of the users."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/viewer\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Replaced the overly permissive 'roles/editor' with 'roles/viewer' to limit access to read-only permissions. This reduces the risk of privilege escalation or accidental changes."
}
